  const checkpointNo = Number(args.checkpoint);
  const checkpointKind = args['checkpoint-kind'];
  const transcriptPath = args.transcript;
  const maxBytes = args['segment-max-bytes'] ? Number(args['segment-max-bytes']) : MAX_BYTES_DEFAULT;
  const prevPacketPath = args['prev-packet'];

  if (!transcriptPath) throw new Error('--transcript is required');
  if (!checkpointKind) throw new Error('--checkpoint-kind is required');
  if (!Number.isInteger(checkpointNo) || checkpointNo < 1) throw new Error('--checkpoint must be an integer >= 1');
  if (!CHECKPOINT_KINDS.has(checkpointKind)) throw new Error('--checkpoint-kind is not a frozen checkpoint kind');
  if (!Number.isInteger(maxBytes) || maxBytes < 4) throw new Error('--segment-max-bytes must be an integer >= 4');

  const buffer = fs.readFileSync(transcriptPath);
  if (buffer.length === 0) throw new Error('--transcript must not be empty');
  const chunks = utf8SafeChunks(buffer, maxBytes);

  let prevHash = null;
  let sequenceNo = 1;
  if (prevPacketPath) {
    const prevPackets = readJson(prevPacketPath);
    if (!Array.isArray(prevPackets) || prevPackets.length === 0) throw new Error('--prev-packet must contain a non-empty packet array');
    const previousVerdict = verifyChain(prevPackets);
    if (!previousVerdict.ok) throw new Error(`--prev-packet chain is invalid: ${previousVerdict.errors.join('; ')}`);
    if (prevPackets.some((packet) => packet.run_id !== runId)) throw new Error('--prev-packet belongs to a different run');
    const last = prevPackets[prevPackets.length - 1];
    if (!Number.isInteger(last.sequence_no) || typeof last.segment_hash !== 'string') {
      throw new Error('--prev-packet has an invalid terminal packet');
    }
    if (Number(last.checkpoint_no) >= checkpointNo) {
      throw new Error('--checkpoint must increase beyond the prior packet checkpoint');
    }
    prevHash = last.segment_hash;
    sequenceNo = last.sequence_no + 1;
  }

  let byteOffset = 0;
  const packets = [];
  for (let i = 0; i < chunks.length; i += 1) {
    const chunk = chunks[i];
    const segmentHash = sha256Buffer(chunk);
    packets.push({
      run_id: runId,
      checkpoint_no: checkpointNo,
      checkpoint_kind: checkpointKind,
      sequence_no: sequenceNo,
      segment_no: i + 1,
      segment_count: chunks.length,
      time_range: args['time-range'] || 'FIXTURE',
      source_locator: `${path.basename(transcriptPath)}:bytes=${byteOffset}-${byteOffset + chunk.length - 1}`,
